<?php
$branches = rows('SELECT id,branch_name FROM branches ORDER BY branch_name');
$teachers = rows('SELECT id,full_name FROM teachers ORDER BY full_name');
$filterBranch = query_int('branch'); $filterTeacher = query_int('teacher'); $filterDay = query_int('day');
$keyword = trim((string)($_GET['q'] ?? ''));
$where=[]; $params=[];
if ($filterBranch) { $where[]='s.branch_id=?'; $params[]=$filterBranch; }
if ($filterTeacher) { $where[]='s.teacher_id=?'; $params[]=$filterTeacher; }
if ($filterDay) { $where[]='s.day_of_week=?'; $params[]=$filterDay; }
if ($keyword !== '') { $where[]='(s.subject_name LIKE ? OR s.room LIKE ? OR t.full_name LIKE ?)'; $search='%'.$keyword.'%'; array_push($params,$search,$search,$search); }
$list = rows('SELECT s.*, t.full_name, b.branch_name FROM schedules s JOIN teachers t ON t.id=s.teacher_id JOIN branches b ON b.id=s.branch_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY s.day_of_week,s.period_start,t.full_name', $params);
?>
<div class="page-heading heading-with-action"><div><div class="eyebrow">QUẢN LÝ HỌC VỤ</div><h1>Lịch giảng dạy <span class="heading-dot">.</span></h1><p>Quản lý phân công, tra cứu và kiểm soát xung đột lịch dạy.</p></div><a class="btn btn-primary" href="<?= e(app_url('schedule-form')) ?>"><svg><use href="#i-plus"/></svg> Thêm lịch dạy</a></div>
<section class="panel"><form class="search-filters" method="get"><input type="hidden" name="page" value="schedules"><div class="search-box"><svg><use href="#i-search"/></svg><input name="q" value="<?= e($keyword) ?>" placeholder="Tìm học phần, phòng, giảng viên..." aria-label="Tìm kiếm"></div><select name="branch"><option value="">Mọi cơ sở</option><?php foreach ($branches as $b): ?><option value="<?= (int)$b['id'] ?>"<?= chosen($filterBranch,$b['id']) ?>><?= e($b['branch_name']) ?></option><?php endforeach; ?></select><select name="teacher"><option value="">Mọi giảng viên</option><?php foreach ($teachers as $t): ?><option value="<?= (int)$t['id'] ?>"<?= chosen($filterTeacher,$t['id']) ?>><?= e($t['full_name']) ?></option><?php endforeach; ?></select><select name="day"><option value="">Mọi thứ</option><?php foreach(day_names() as $number=>$name): ?><option value="<?= $number ?>"<?= chosen($filterDay,$number) ?>><?= e($name) ?></option><?php endforeach; ?></select><button class="btn btn-dark btn-sm" type="submit">Lọc</button><a class="btn btn-ghost btn-sm" href="<?= e(app_url('schedules')) ?>">Xóa lọc</a></form>
<div class="table-topline"><strong><?= count($list) ?> lịch dạy</strong><span>Tất cả lịch lặp lại mỗi tuần</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>MÔN HỌC / HỌC PHẦN</th><th>GIẢNG VIÊN</th><th>CƠ SỞ</th><th>THỨ / TIẾT</th><th>PHÒNG</th><th class="actions-col">THAO TÁC</th></tr></thead><tbody><?php foreach($list as $item): ?><tr><td><strong><?= e($item['subject_name']) ?></strong><small class="subtle">#<?= (int)$item['id'] ?></small></td><td><span class="avatar-inline"><?= e(initials($item['full_name'])) ?></span><?= e($item['full_name']) ?></td><td><span class="cell-max"><?= e($item['branch_name']) ?></span></td><td><span class="tag-blue"><?= e(short_day((int)$item['day_of_week'])) ?></span> <?= e(period_label((int)$item['period_start'],(int)$item['period_end'])) ?></td><td><span class="room-pill"><?= e($item['room']) ?></span></td><td><div class="row-actions"><a class="action-edit" href="<?= e(app_url('schedule-form',['id'=>$item['id']])) ?>">Sửa</a><form method="post" action="<?= e(app_url('schedules')) ?>" data-confirm="Xóa lịch <?= e($item['subject_name']) ?>?"><?= csrf_field() ?><input type="hidden" name="action" value="delete-schedule"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="action-delete" type="submit">Xóa</button></form></div></td></tr><?php endforeach; ?><?php if(!$list): ?><tr><td colspan="6" class="table-empty">Không tìm thấy lịch dạy phù hợp với bộ lọc.</td></tr><?php endif; ?></tbody></table></div></section>
